      "title": "首次成功实现！“量子计算不再受制于人”",
      "summary": "首页 从92%到99.99%国产高纯硅量产 量子计算不再受制于人 分享到： 中核集团核工业理化工程研究院15日介绍，我国科学家在稳定同位素富集与高纯硅制备领域取得关键性突破，首次成功实现丰度超过99.99%的硅-28同位素自主量产，产品关键指标达到国际先进水平。科研团队介绍，这项科研突破，将为我国硅基量子计算芯片的自主",
